"""Certified splitting type of x^4 - 10x^2 + 1 modulo a prime p >= 5."""
from __future__ import annotations


def legendre(a: int, p: int) -> int:
    """Euler's criterion: returns 1, -1 or 0."""
    t = pow(a % p, (p - 1) // 2, p)
    return -1 if t == p - 1 else t


def tonelli_shanks(a: int, p: int) -> int:
    """A square root of the quadratic residue a modulo the odd prime p."""
    a %= p
    if a == 0:
        return 0
    q, s = p - 1, 0
    while q % 2 == 0:
        q //= 2
        s += 1
    z = 2
    while legendre(z, p) != -1:
        z += 1
    m, c, t, r = s, pow(z, q, p), pow(a, q, p), pow(a, (q + 1) // 2, p)
    while t != 1:
        i, t2 = 0, t
        while t2 != 1:
            t2 = t2 * t2 % p
            i += 1
        b = pow(c, 1 << (m - i - 1), p)
        m, c, t, r = i, b * b % p, t * b * b % p, r * b % p
    return r


def certified_type(p: int) -> dict[str, object]:
    """Type from p mod 24, together with an independently checkable certificate."""
    assert p >= 5
    predicted = 4 if p % 24 in (1, 23) else 0
    f = lambda x: (pow(x, 4, p) - 10 * x * x + 1) % p
    if predicted == 4:
        al, be = tonelli_shanks(2, p), tonelli_shanks(3, p)
        roots = sorted({(s * al + t * be) % p for s in (1, -1) for t in (1, -1)})
        assert len(roots) == 4 and all(f(x) == 0 for x in roots)
        return {"p": p, "type": 4, "roots": roots}
    for d, shape in ((2, "a"), (3, "b"), (6, "ab")):
        if legendre(d, p) == 1:
            r = tonelli_shanks(d, p)
            if shape == "a":
                fac = ((-2 * r) % p, p - 1, (2 * r) % p, p - 1)
            elif shape == "b":
                fac = ((-2 * r) % p, 1, (2 * r) % p, 1)
            else:
                fac = (0, (-5 - 2 * r) % p, 0, (-5 + 2 * r) % p)
            u, v, w, z = fac
            # check the product of the two quadratics coefficientwise
            prod = [1, (u + w) % p, (v + z + u * w) % p, (u * z + v * w) % p, v * z % p]
            assert prod == [1, 0, (-10) % p, 0, 1]
            return {"p": p, "type": 0, "square": d, "factors": fac}
    raise AssertionError("one of 2, 3, 6 is always a square")


if __name__ == "__main__":
    for p in (5, 7, 23, 73, 1009, 10007, 1000003):
        print(certified_type(p))
